    .setMaxConnPerRoute(50)
    .setMaxConnTotal(100)
    // ✅ 添加连接清理策略
    .evictIdleConnections(30, TimeUnit.SECONDS)  // 清理空闲连接
    .evictExpiredConnections()                   // 清理过期连接
    // ✅ 限制堆外内存分配
    .setDefaultIOReactorConfig(
        IOReactorConfig.custom()
            .setIoThreadCount(4)  # 限制 IO 线程数（减少堆外内存）
            .build()
    )
    .build();

